def link(p):return 'projet-'+p['id']+'.html'
def asset(x):return 'assets/'+x
def taglist(p):return '<div class="tags">'+''.join('<span>'+E(t)+'</span>' for t in p['tags'])+'</div>'
def card(p):
 visual=f'<img src="{asset(p["image"])}" alt="{E(p["gallery"][0]["caption"] if p.get("gallery") else p["title"])}" loading="lazy" width="800" height="540">' if p['image'] else '<div class="text-cover"><span>MÉMOIRE / 2025</span><strong>Matériaux.<br>Structures.<br><i>Rupture.</i></strong><small>IMSP · Université d’Abomey-Calavi</small></div>'
 return f'''<article class="project-card" data-category="{E(p['category'])}"><a href="{link(p)}" class="project-image {p['id']}">{visual}<span class="image-action" aria-hidden="true">Explorer ↗</span></a><div class="project-meta"><span>{E(p['domain'])}</span><time>{E(p['year'])}</time></div><h3><a href="{link(p)}">{E(p['title'])} <span aria-hidden="true">↗</span></a></h3><p>{E(p['summary'])}</p><div class="evidence"><strong>{E(p['evidence'])}</strong><span>{E(p['evidence_note'])}</span></div><small class="collaboration">{E(p['collaboration'])}</small></article>'''
def report(p):
 r=p['report'];size=(SRC/asset(r['file'])).stat().st_size/1000000
 return f'''<a class="document-row" href="{asset(r['file'])}" target="_blank" rel="noopener"><span class="doc-type">PDF</span><span><strong>{E(r['title'])}</strong><small>{E(r['kind'])} · {size:.1f} Mo</small></span><span class="doc-open">Ouvrir ↗</span></a>'''
def video(d):
 track=f'<track src="{asset(d["track"])}" kind="captions" srclang="fr" label="Français" default>' if d.get('track') else ''
 chapters=''.join(f'<button type="button" data-seek="{c["time"]}"><time>{c["time"]//60}:{c["time"]%60:02}</time> {E(c["title"])}</button>' for c in d.get('chapters',[]))
 return f'''<section class="film"><div class="film-heading"><h3>{E(d['title'])}</h3><span>{E(d['duration'])}</span></div><video controls playsinline crossorigin="anonymous" preload="none" poster="{asset(d['poster'])}" aria-label="{E(d['title'])}"><source src="{asset(d['src'])}" type="video/{'mp4' if d['src'].endswith('.mp4') else 'webm'}">{track}<a href="{asset(d['src'])}">Ouvrir la vidéo</a></video><div class="chapters">{chapters}</div><p class="caption">{E(d['caption'])}</p></section>'''
